1202:pub fn fork_replay_guard(thread: &str, codex_home: &str, max_kb_env: Option<&str>) -> ForkGuard {
1203:    let mut g = ForkGuard {
1204:        max_kb: FORK_MAX_KB_DEFAULT,
1205:        ..Default::default()
1206:    };
1207:    let raw = max_kb_env.map(str::trim).unwrap_or("");
1208:    if !raw.is_empty() {
1209:        match raw.parse::<i32>() {
1210:            Ok(v) if v >= 0 => g.max_kb = v as i64,
1211:            _ => {
1212:                g.problem = format!(
1213:                    "CODEX_CONSULT_FORK_MAX_KB='{raw}' is not a number of KB (0 = no limit) - the default 512 applies"
1214:                )
1215:            }
1216:        }
1217:    }
1218:    if thread.is_empty() {
1219:        return g;
1220:    }
1221:    let path = match codex_rollout_path(thread, codex_home) {
1222:        Some(p) => p,
1223:        None => return g,
1224:    };
1225:    g.bytes = match std::fs::metadata(&path) {
1226:        Ok(m) => m.len(),
1227:        Err(_) => {
1228:            g.path = Some(path);
1229:            return g;
1230:        }
1231:    };
1232:    g.path = Some(path);
1233:    g.kb = round_even(g.bytes as f64 / 1024.0);
1234:    let tokens_k = round_even(g.kb as f64 / 4.0);
1235:    let what = format!(
1236:        "the parent thread {thread} replays {} KB (~{tokens_k} k tokens) on EVERY tool call of the run",
1237:        g.kb
1238:    );
1239:    if g.max_kb > 0 && g.kb > g.max_kb {
1240:        g.over_limit = true;
1241:        g.refusal = format!(
1242:            "{what}: use -Mode new, or raise CODEX_CONSULT_FORK_MAX_KB (now {})",
1243:            g.max_kb
1244:        );
1245:    } else if g.kb >= FORK_WARN_KB {
1246:        let lim = if g.max_kb > 0 {
1247:            g.max_kb.to_string()
1248:        } else {
1249:            "off".into()
1250:        };
1251:        g.warning = format!(
1252:            "{what} (CODEX_CONSULT_FORK_MAX_KB {lim}); -Mode new starts without that replay"
1253:        );
1254:    }
1255:    g
1256:}
